mapper.select:
SELECT id, code, name, display_order, is_visible
FROM diary_sticker_categories
WHERE id = #{id}

mapper.update:
UPDATE diary_sticker_categories
SET name = #{name}, display_order = #{displayOrder}, is_visible = #{visible}
WHERE id = #{id}

mapper.select:
SELECT 
FROM diary_stickers s
JOIN diary_sticker_categories c ON c.id = s.category_id
WHERE s.catalog_key NOT LIKE 'history-%'

    AND s.category_id = #{categoryId}


    AND s.sticker_type = #{stickerType}


    AND s.access_tier = #{accessTier}


    AND s.is_visible = #{visible}

ORDER BY c.display_order ASC, c.id ASC, s.display_order ASC, s.id ASC
